  async function downloadBytes(path,name,current,expected){
    const response=await fetch(path,{redirect:'error',headers:{authorization:'Bearer '+NXT.key.get()}});
    if(!current())return;
    if(!response.ok){const body=await response.json().catch(()=>({}));throw Error(body.error||'Output unavailable.');}
    const blob=await response.blob();if(!current())return;
    if(blob.size>4*1024*1024)throw Error('Output exceeds the supported download size.');
    if(expected){
      if(blob.size!==expected.bytes)throw Error('File length does not match its retained version; no download was created.');
      const digest=await crypto.subtle.digest('SHA-256',await blob.arrayBuffer());
      if(!current())return;
      if(Array.from(new Uint8Array(digest),n=>n.toString(16).padStart(2,'0')).join('')!==expected.sha256)throw Error('File hash does not match its retained version; no download was created.');
    }
    if(!current())return;
    const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('Saved output downloaded');
  }
